#!/usr/bin/env python3
"""Mini-Core parser, monotype checker, and lexical-address bytecode VM."""
import re
import sys

sys.set_int_max_str_digits(0)
sys.setrecursionlimit(1000000)

class ParseFail(Exception): pass
class TypeFail(Exception): pass

TOKEN = re.compile(r'[ \t\r\n\v\f]+|--[^\r\n]*|[a-zA-Z_][A-Za-z0-9_]*|[0-9]+|->|//|==|[()/:=*+%<-]|.', re.ASCII)
RESERVED = {'let','rec','in','if','then','else','match','with','type','forall','_'}
def ident(t):
    return ('a' <= t[0] <= 'z' or t[0] == '_') and t not in RESERVED

class Parser:
    def __init__(self, source):
        self.tokens = [m[0] for m in TOKEN.finditer(source) if not (m[0][0].isspace() and m[0][0] in ' \t\r\n\f\v') and not m[0].startswith('--')]
        self.tokens.append('@EOF')
        self.i = 0
        self.t = self.tokens[0]
    def pop(self):
        t = self.t
        self.i += 1
        self.t = self.tokens[self.i]
        return t
    def eat(self,t):
        if self.t == t:
            self.pop()
            return True
        return False
    def need(self,t):
        if not self.eat(t): raise ParseFail
    def name(self):
        if not ident(self.t): raise ParseFail
        return self.pop()
    def ty(self):
        if self.eat('('):
            a = self.ty(); self.need(')')
        elif self.t in ('Int','Bool'): a = self.pop()
        else: raise ParseFail
        if self.eat('->'): return (a,self.ty())
        return a
    def expr(self):
        if self.eat('/'):
            n = self.name(); self.need('->')
            return ('lam',n,self.expr())
        if self.eat('let'):
            rec = self.eat('rec'); n = self.name()
            ty = self.ty() if self.eat(':') else None
            self.need('='); a = self.expr(); self.need('in')
            if rec and (ty is None or a[0] != 'lam'): raise ParseFail
            return ('rec' if rec else 'let',n,ty,a,self.expr())
        if self.eat('if'):
            c = self.expr(); self.need('then'); a = self.expr(); self.need('else')
            return ('if',c,a,self.expr())
        a = self.add()
        if self.t in ('<','=='): a = (self.pop(),a,self.add())
        return a
    def add(self):
        a = self.mul()
        while self.t in ('+','-'): a = (self.pop(),a,self.mul())
        return a
    def mul(self):
        a = self.app()
        while self.t in ('*','//','%'): a = (self.pop(),a,self.app())
        return a
    def app(self):
        a = self.atom()
        while self.t in ('(','True','False') or ident(self.t) or self.t[0].isdigit():
            a = ('app',a,self.atom())
        return a
    def atom(self):
        if self.eat('('):
            a = self.expr()
            if self.eat(':'): a = ('ann',a,self.ty())
            self.need(')'); return a
        if self.t in ('True','False'): return ('bool',self.pop() == 'True')
        if ident(self.t): return ('var',self.pop())
        if self.t[0].isdigit(): return ('int',int(self.pop()))
        raise ParseFail
    def program(self):
        e = self.expr()
        if self.t != '@EOF': raise ParseFail
        return e

# Types are base names, arrow pairs, or mutable metavariables. Only unknowns
# carry substitutions. Never instantiate a fresh copy at a variable use.
class Hole:
    __slots__ = ('link',)
    def __init__(self): self.link = None

def root(x):
    if type(x) is Hole and x.link is not None:
        r = x
        while type(r) is Hole and r.link is not None: r = r.link
        while x is not r: x.link,x = r,x.link
        return r
    return x

def occurs(v,t):
    todo = [t]; seen = set()
    while todo:
        x = root(todo.pop())
        if x is v: return True
        if type(x) is tuple and id(x) not in seen:
            seen.add(id(x)); todo.extend(x)
    return False

def unify(a,b):
    todo = [(a,b)]; seen = set()
    while todo:
        x,y = todo.pop(); x,y = root(x),root(y)
        if x is y: continue
        if type(y) is Hole: x,y = y,x
        if type(x) is Hole:
            if type(y) is tuple and occurs(x,y): raise TypeFail
            x.link = y
        elif type(x) is tuple and type(y) is tuple:
            k = (id(x),id(y))
            if k not in seen:
                seen.add(k); todo.append((x[0],y[0])); todo.append((x[1],y[1]))
        elif type(x) is tuple or type(y) is tuple or x != y: raise TypeFail

class Compiler:
    def __init__(self):
        self.code = []
        self.scope = {}; self.depth = 0
    def push(self,n,t):
        self.scope.setdefault(n,[]).append((self.depth,t)); self.depth += 1
    def pop(self,n):
        self.scope[n].pop(); self.depth -= 1
    def emit(self,op,arg=None):
        self.code.append((op,arg)); return len(self.code)-1
    def patch(self,i): self.code[i] = (self.code[i][0],len(self.code))
    def compile(self,e,tail=False):
        k = e[0]
        if k in ('int','bool'):
            self.emit('const',e[1]); return 'Int' if k == 'int' else 'Bool'
        if k == 'var':
            b = self.scope.get(e[1])
            if not b: raise TypeFail
            d,t = b[-1]; self.emit('load',self.depth - 1 - d); return t
        if k == 'lam':
            # MAKE saves the following instruction address as the entry point,
            # then skips over the body to its patched target.
            i = self.emit('make'); t = Hole(); self.push(e[1],t)
            r = self.compile(e[2],True); self.pop(e[1]); self.emit('ret'); self.patch(i)
            return (t,r)
        if k == 'app':
            f = self.compile(e[1]); a = self.compile(e[2]); r = Hole(); unify(f,(a,r))
            self.emit('tail' if tail else 'call'); return r
        if k == 'ann':
            unify(self.compile(e[1],tail),e[2]); return e[2]
        if k == 'if':
            unify(self.compile(e[1]),'Bool'); i = self.emit('jfalse'); t = self.compile(e[2],tail)
            j = self.emit('jmp'); self.patch(i); unify(t,self.compile(e[3],tail)); self.patch(j); return t
        if k in ('let','rec'):
            _,n,t,a,b = e
            if k == 'rec': self.push(n,t); self.emit('placeholder')
            r = self.compile(a)
            if t is not None: unify(t,r)
            if k == 'rec': self.emit('fill')
            else: self.emit('bind'); self.push(n,r)
            z = self.compile(b,tail); self.pop(n)
            if not tail: self.emit('unbind')
            return z
        unify(self.compile(e[1]),'Int'); unify(self.compile(e[2]),'Int'); self.emit(k)
        return 'Bool' if k in ('<','==') else 'Int'

def execute(code):
    pc = 0; env = None; stack = []; calls = []
    while True:
        op,x = code[pc]; pc += 1
        if op == 'load':
            p = env
            while x: p = p[1]; x -= 1
            stack.append(p[0])
        elif op == 'const': stack.append(x)
        elif op == 'call' or op == 'tail':
            a = stack.pop(); dest,captured = stack.pop()
            if op == 'call': calls.append((pc,env))
            pc = dest; env = (a,captured)
        elif op == 'ret': pc,env = calls.pop()
        elif op == 'make': stack.append((pc,env)); pc = x
        elif op == 'jfalse':
            if not stack.pop(): pc = x
        elif op == 'jmp': pc = x
        elif op == '+': v = stack.pop(); stack[-1] += v
        elif op == '-': v = stack.pop(); stack[-1] -= v
        elif op == '*': v = stack.pop(); stack[-1] *= v
        elif op == '<': v = stack.pop(); stack[-1] = stack[-1] < v
        elif op == '==': v = stack.pop(); stack[-1] = stack[-1] == v
        elif op == '//': v = stack.pop(); stack[-1] //= v
        elif op == '%': v = stack.pop(); stack[-1] %= v
        elif op == 'bind': env = (stack.pop(),env)
        elif op == 'unbind': env = env[1]
        elif op == 'placeholder': env = [None,env]
        elif op == 'fill': env[0] = stack.pop()
        elif op == 'halt': return stack.pop()

def main(path):
    try:
        with open(path,'rb') as f: src = f.read().decode('ascii')
        tree = Parser(src).program()
    except (UnicodeError,ParseFail): print('ParseError'); return 1
    c = Compiler()
    try: c.compile(tree); c.emit('halt')
    except TypeFail: print('TypeError'); return 1
    try: value = execute(c.code)
    except ZeroDivisionError: print('RuntimeError'); return 1
    print('<function>' if type(value) is tuple else value)
    return 0

if __name__ == '__main__':
    sys.exit(main(sys.argv[2]))
